import { constants } from "node:fs";
import { lstat, open, realpath } from "node:fs/promises";
import { extname, sep } from "node:path";
import { callSlackApiSoft } from "./api.js";
const ALLOWED = new Set([
    ".png",
    ".jpg",
    ".jpeg",
    ".gif",
    ".webp",
    ".svg",
    ".pdf",
    ".html",
    ".txt",
    ".log",
    ".json",
    ".csv",
    ".md",
    ".mp4",
    ".mov",
    ".webm",
]);
const MAX_BYTES = 50 * 1024 * 1024;
/** Copy into a `Uint8Array` backed by `ArrayBuffer`, which `fetch` accepts as a body. */
function arrayBufferBytes(bytes) {
    const copy = new Uint8Array(bytes.byteLength);
    copy.set(bytes);
    return copy;
}
async function readJailed(file) {
    if (file.workspace === "") {
        return `${file.name}: missing workspace`;
    }
    const info = await lstat(file.path);
    if (info.isSymbolicLink() || !info.isFile()) {
        return `${file.name}: not a regular file`;
    }
    const real = await realpath(file.path);
    const root = await realpath(file.workspace);
    if (real !== root && !real.startsWith(`${root}${sep}`)) {
        return `${file.name}: outside workspace`;
    }
    const nofollow = constants.O_NOFOLLOW;
    const flags = nofollow === undefined ? constants.O_RDONLY : constants.O_RDONLY | nofollow;
    const handle = await open(file.path, flags);
    try {
        const bytes = await handle.readFile();
        if (bytes.byteLength > MAX_BYTES) {
            return `${file.name}: over the upload cap`;
        }
        const extension = extname(file.path).toLowerCase();
        if (!ALLOWED.has(extension)) {
            return `${file.name}: type Slack does not render`;
        }
        return bytes;
    }
    finally {
        await handle.close();
    }
}
export async function uploadThreadFiles(args) {
    if (args.files.length === 0) {
        return [];
    }
    const failures = [];
    const uploaded = [];
    for (const file of args.files) {
        let bytes;
        try {
            const read = await readJailed(file);
            if (typeof read === "string") {
                failures.push(read);
                continue;
            }
            bytes = read;
        }
        catch (error) {
            failures.push(`${file.name}: gone before upload (${String(error)})`);
            continue;
        }
        const reserveBody = {
            filename: file.name,
            length: bytes.byteLength,
        };
        if (file.altTxt !== undefined) {
            reserveBody.alt_txt = file.altTxt;
        }
        const reserved = await callSlackApiSoft({
            botToken: args.botToken,
            operation: "files.getUploadURLExternal",
            body: reserveBody,
        });
        if (!reserved.ok) {
            failures.push(`${file.name}: could not reserve upload (${reserved.error})`);
            continue;
        }
        const uploadUrl = reserved.upload_url;
        const fileId = reserved.file_id;
        if (typeof uploadUrl !== "string" || typeof fileId !== "string") {
            failures.push(`${file.name}: could not reserve upload (malformed reserve response)`);
            continue;
        }
        try {
            const put = await fetch(uploadUrl, {
                method: "POST",
                body: arrayBufferBytes(bytes),
            });
            if (!put.ok) {
                failures.push(`${file.name}: upload returned ${put.status}`);
                continue;
            }
        }
        catch (error) {
            failures.push(`${file.name}: upload failed (${String(error)})`);
            continue;
        }
        uploaded.push({
            id: fileId,
            title: file.name,
            initialComment: file.initialComment,
        });
    }
    if (uploaded.length === 0) {
        return failures;
    }
    // One complete call shares every file with the same caption, including
    // none. A different caption is its own call so the text stays with those files.
    const groups = new Map();
    for (const file of uploaded) {
        const key = file.initialComment ?? "";
        const group = groups.get(key);
        if (group === undefined) {
            groups.set(key, [{ id: file.id, title: file.title }]);
        }
        else {
            group.push({ id: file.id, title: file.title });
        }
    }
    for (const [comment, files] of groups) {
        const completeBody = {
            files,
            channel_id: args.channelId,
            thread_ts: args.threadTs,
        };
        if (comment !== "") {
            completeBody.initial_comment = comment;
        }
        const shared = await callSlackApiSoft({
            botToken: args.botToken,
            operation: "files.completeUploadExternal",
            body: completeBody,
        });
        if (!shared.ok) {
            const titles = files.map((file) => file.title).join(", ");
            failures.push(`${titles}: could not share (${shared.error})`);
        }
    }
    return failures;
}
